// BAD: In-memory session pins user requests to a specific server instance
const localSessions = new Map<string, UserSession>();

// GOOD: Externalized session state allows any worker node to handle the request
export async function authenticateRequest(req: Request, redis: RedisClient) {
  const sessionId = req.headers.get("x-session-id");
  if (!sessionId) throw new Error("Unauthorized");
  // Any of the 200 application containers can validate this in under 1ms
  const payload = await redis.get(`session:${sessionId}`);
  return payload ? JSON.parse(payload) : null;
}

// Series: Any single component failure takes down the request path
export function calculateSeriesAvailability(availabilities: number[]): number {
  return availabilities.reduce((acc, curr) => acc * curr, 1);
}

// Parallel: The path stays available unless ALL redundant replicas fail
export function calculateParallelAvailability(replicaAvailability: number, replicaCount: number): number {
  const failureProb = 1 - replicaAvailability;
  return 1 - Math.pow(failureProb, replicaCount);
}

// Two 99.9% nodes in parallel yield 99.9999% (Six Nines)!

export async function hedgedRead<T>(
  primaryCall: () => Promise<T>,
  backupCall: () => Promise<T>,
  p95ThresholdMs = 20
): Promise<T> {
  return new Promise((resolve, reject) => {
    let completed = false;
    const timer = setTimeout(() => {
      // Primary is taking too long; fire backup replica concurrently
      backupCall().then((res) => {
        if (!completed) { completed = true; resolve(res); }
      }).catch(() => {});
    }, p95ThresholdMs);

    primaryCall().then((res) => {
      clearTimeout(timer);
      if (!completed) { completed = true; resolve(res); }
    }).catch((err) => { if (!completed) reject(err); });
  });
}

interface QuorumConfig {
  replicationFactorN: number; // e.g., 3 replicas
  writeQuorumW: number;       // Nodes that must acknowledge write
  readQuorumR: number;        // Nodes queried on read
}

// Strict Quorum (CP / Linearizable): W + R > N
// The read set is mathematically guaranteed to overlap with the write set
export const strictQuorum: QuorumConfig = {
  replicationFactorN: 3,
  writeQuorumW: 2,
  readQuorumR: 2,
};

// Sloppy Quorum (AP / Low Latency): W + R <= N
// Fast and partition-tolerant, but reads can return stale data
export const highAvailabilityConfig: QuorumConfig = {
  replicationFactorN: 3,
  writeQuorumW: 1,
  readQuorumR: 1,
};

// After writing to Primary DB, return the Log Sequence Number (LSN) token
// Route reads to replicas only if they have caught up to the client's write LSN
export async function readUserProfile(
  userId: string,
  clientSeenLsn: bigint,
  primaryDb: DbNode,
  replicaDb: DbNode
) {
  const replicaCurrentLsn = await replicaDb.getReplicationLsn();
  if (replicaCurrentLsn >= clientSeenLsn) {
    return replicaDb.query("SELECT * FROM users WHERE id = $1", [userId]);
  }
  // Replica is lagging; route directly to primary to prevent stale read
  return primaryDb.query("SELECT * FROM users WHERE id = $1", [userId]);
}

-- Without row locking or optimistic checks, concurrent requests both read
-- status='AVAILABLE' and overwrite each other's reservation.
BEGIN TRANSACTION;

-- Acquire an exclusive row-level lock
SELECT seat_id, status FROM concert_seats
WHERE seat_id = 'A12' AND status = 'AVAILABLE'
FOR UPDATE;

-- If available, update status and record booking atomically
UPDATE concert_seats SET status = 'BOOKED', user_id = 'u_101' WHERE seat_id = 'A12';
INSERT INTO bookings (booking_id, seat_id, user_id) VALUES ('b_901', 'A12', 'u_101');

COMMIT;

// 1. API Gateway: Fast admission and enqueue (<15ms response)
export async function handleVideoUpload(req: UploadRequest, queue: QueueClient) {
  const jobId = crypto.randomUUID();
  await queue.publish("video-transcode-jobs", {
    jobId,
    s3Key: req.s3Key,
    resolutions: ["1080p", "720p", "480p"],
    attempt: 1,
  });
  return { status: 202, jobId, statusUrl: `/api/v1/jobs/${jobId}` };
}

// 2. Worker: Retries with exponential backoff and routes poison pills to DLQ
export async function processJob(msg: JobMessage, queue: QueueClient) {
  try {
    await transcodeFfmpeg(msg.s3Key, msg.resolutions);
  } catch (err) {
    if (msg.attempt >= 5) {
      await queue.publish("video-transcode-DLQ", { ...msg, error: String(err) });
    } else {
      const backoffMs = Math.pow(2, msg.attempt) * 1000 + Math.random() * 500;
      await queue.publishDelayed("video-transcode-jobs", { ...msg, attempt: msg.attempt + 1 }, backoffMs);
    }
  }
}
